/* prog19_palindrome_checker.c
 * Re‑implementation of the original behaviour extracted from the
 * obfuscated binary.  The program reads at most one command‑line
 * argument, normalises it (keeps only alphanumerics, lower‑cases
 * letters) and checks whether the normalised string is a palindrome.
 *
 * Output:
 *   - "TOO_LONG"        if the *original* argument length > 1024
 *   - "PALINDROME"      if the normalised string is a palindrome
 *   - "NOT_PALINDROME"  otherwise
 *
 * If no argument is supplied the empty string is treated as a
 * palindrome (the original binary behaved this way).
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_RAW_LEN 1024   /* 0x400 */

int main(int argc, char *argv[])
{
    const char *input;
    size_t raw_len;

    /* 1. Choose the string to analyse */
    if (argc > 1) {
        input = argv[1];
    } else {
        input = "";
    }

    raw_len = strlen(input);

    /* 2. Length limit */
    if (raw_len > MAX_RAW_LEN) {
        puts("TOO_LONG");
        return 0;
    }

    /* 3. Normalisation: keep alphanumerics, lower‑case letters */
    char norm[MAX_RAW_LEN + 1];   /* normalised string can never be longer */
    size_t n = 0;
    for (size_t i = 0; i < raw_len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            norm[n++] = (char)tolower(c);
        }
    }
    norm[n] = '\0';

    /* 4. Palindrome test */
    int is_pal = 1;
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    /* 5. Result */
    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
